	case limit <= 0:
		reason = fmt.Sprintf("委托限价必须为正: %d", limit)
	}

	e.mu.Lock()
	defer e.mu.Unlock()

	st := e.state(symbol)

	if reason == "" && side == Buy && e.riskOpen && e.riskRestricted {
